insert into research_companies (name, industry, seg, listed, round, cap, valuation, last_funding, data) values
  ('长沙韶光芯材', 'semiconductor', 'material', false, 'C+ 轮', null, null, '2026-06', '{"name":"长沙韶光芯材","industry":"semiconductor","seg":"material","listed":false,"desc":"国内最早布局半导体光掩模基板的本土厂商，前身溯源至 1980 年国家立项集成电路配套专项。已打通石英基板研磨抛光—磁控溅射镀膜—光刻胶涂覆全链条自研工艺，产品覆盖 I/G-line、KrF、ArF 多代制程，批量供货国内头部晶圆制造与掩模版企业。国家级专精特新「小巨人」、湖南省制造业单项冠军。","round":"C+ 轮","lastFunding":"2026-06","tech":[{"date":"2026-06","title":"完成 3.4 亿元 C+ 轮融资","kind":"融资","desc":"上汽金控、尚颀资本主力出资，元禾控股、金浦投资、熙诚金睿、前海母基金、华富嘉业、恒坤新材、盛盎投资同步参投。累计融资超 12 亿元，超 30 家机构入场。"},{"date":"2025-12","title":"完成 3.8 亿元 C 轮融资","kind":"融资","desc":"引入中国建材、中金资本、建投华文、达晨财智等机构。"},{"date":"2024-12","title":"B 轮、B+ 轮合计近 4 亿元","kind":"融资","desc":"上海宝鼎资本、达晨财智分别领投。"},{"date":"2022-08","title":"A 轮及 A+ 轮融资近亿元","kind":"融资","desc":"上海新微领投，深圳高新投、中车时代高新投入局。"}],"funding":[{"date":"2026-06","round":"C+ 轮","amount":"3.4 亿元","investors":"上汽金控 · 尚颀资本（主力）· 元禾控股 · 金浦投资 · 熙诚金睿 · 前海母基金 · 华富嘉业 · 恒坤新材 · 盛盎投资"},{"date":"2025-12","round":"C 轮","amount":"3.8 亿元","investors":"中国建材 · 中金资本 · 建投华文 · 达晨财智"},{"date":"2024-12","round":"B+ 轮","amount":"（与 B 轮合计近 4 亿元）","investors":"达晨财智（领投）"},{"date":"2024-06","round":"B 轮","amount":"（与 B+ 轮合计近 4 亿元）","investors":"上海宝鼎资本（领投）"},{"date":"2022-08","round":"A+ 轮","amount":"（与 A 轮合计近亿元）","investors":"深圳高新投 · 中车时代高新投"},{"date":"2022-08","round":"A 轮","amount":"（与 A+ 轮合计近亿元）","investors":"上海新微（领投）"}],"investorsStructured":[{"name":"上汽金控","role":"lead","round":"C+ 轮","date":"2026-06","kind":"cvc","note":"上汽集团直属产业投资平台"},{"name":"尚颀资本","role":"lead","round":"C+ 轮","date":"2026-06","kind":"cvc","note":"上汽产业资本体系"},{"name":"元禾控股","role":"follow","round":"C+ 轮","date":"2026-06","kind":"gov"},{"name":"金浦投资","role":"follow","round":"C+ 轮","date":"2026-06","kind":"pe"},{"name":"前海母基金","role":"follow","round":"C+ 轮","date":"2026-06","kind":"gov"},{"name":"熙诚金睿","role":"follow","round":"C+ 轮","date":"2026-06","kind":"pe"},{"name":"华富嘉业","role":"follow","round":"C+ 轮","date":"2026-06","kind":"other"},{"name":"恒坤新材","role":"strategic","round":"C+ 轮","date":"2026-06","kind":"cvc","note":"产业链实体企业，光刻材料厂商"},{"name":"盛盎投资","role":"follow","round":"C+ 轮","date":"2026-06","kind":"other"},{"name":"中国建材","role":"strategic","round":"C 轮","date":"2025-12","kind":"cvc"},{"name":"中金资本","role":"follow","round":"C 轮","date":"2025-12","kind":"pe"},{"name":"建投华文","role":"follow","round":"C 轮","date":"2025-12","kind":"pe"},{"name":"达晨财智","role":"lead","round":"B+ 轮","date":"2024-12","kind":"vc","note":"连续参与 B+ 轮与 C 轮"},{"name":"上海宝鼎资本","role":"lead","round":"B 轮","date":"2024-06","kind":"pe"},{"name":"深圳高新投","role":"follow","round":"A+ 轮","date":"2022-08","kind":"gov"},{"name":"中车时代高新投","role":"follow","round":"A+ 轮","date":"2022-08","kind":"cvc"},{"name":"上海新微","role":"lead","round":"A 轮","date":"2022-08","kind":"cvc","note":"中科院上海微系统所背景"}],"executives":[{"name":"—","title":"（董事长/核心团队未公开披露）","role":"management"}],"note":"【卡脖子定位】光掩模基板是整条材料链卡得最死的环节：国内月需求约 12 万张，本土产能仅每月两三千张，国产化率约 2%（低于下游掩膜版整体的 10%）。上游高纯合成石英需 9 个 9 纯度，国内普遍停在 5 个 9；28nm 以下高端品类（OMOG / HT PSM / HD PSM）国产基本空白。信越与豪雅垄断国内 90% 以上高端份额，ArF 基板近乎 100% 依赖两家，EUV 基板处于禁运状态。"}'::jsonb),
  ('中科卓尔', 'semiconductor', 'material', false, '战略融资', null, null, '2026-09', '{"name":"中科卓尔","industry":"semiconductor","seg":"material","listed":false,"desc":"成都中科卓尔智能科技集团，依托中国科学院光电所团队成长，攻克超精密抛光、磁控溅射镀膜、缺陷检测三大核心工艺。产品为光刻空白掩模版（光掩模基板），粗糙度低至 0.2 纳米、膜层均匀性控制在 ±2% 以内。","round":"战略融资","lastFunding":"2026-09","tech":[{"date":"2026-09","title":"获成都银行授信，中试线扩容","kind":"产能","desc":"运用「高知贷」「股债通」政策性产品落地授信，设备采购提速、中试线扩容，未来两到三年布局多条先进制程量产线。"},{"date":"2026-07","title":"抛光基板向豪雅、信越、S&S Tech 出货","kind":"客户","desc":"以超精密加工为切口进入日本头部企业供应链。产品总监贾松涛称「在超精密加工环节，我们的部分指标甚至优于豪雅」。"},{"date":"2026-01","title":"二元铬板基板与低端 KrF 节点缺陷密度与日本同数量级","kind":"技术","desc":"最优批次指标差距约 3 至 5 倍；ArF PSM 档与日本仍存在约一个数量级差距。"}],"funding":[{"date":"2026-09","round":"债权融资","amount":"未披露（成都银行授信）","investors":"成都银行（高知贷 · 股债通）"}],"investorsStructured":[{"name":"成都银行","role":"other","round":"授信","date":"2026-09","kind":"other","note":"政策性科创信贷，非股权融资"}],"executives":[{"name":"贾松涛","title":"产品总监","role":"management","bio":"多次代表公司在行业活动中披露国内掩模基板产能与国产化率数据。"}],"note":"【卡脖子定位】与长沙韶光芯材并列为国内少数认真投入光掩模基板的两家。中科卓尔的突破口在超精密抛光环节——已反向进入豪雅、信越供应链（代工姿态），但 ArF PSM、OMOG 等真正对应 28nm 以下节点的高端品类仍是空白。"}'::jsonb),
  ('凯立新材', 'semiconductor', 'material', true, '已上市', null, null, null, '{"name":"凯立新材","industry":"semiconductor","seg":"material","listed":true,"desc":"西安凯立新材料股份有限公司，主营贵金属催化剂研发生产与废旧贵金属催化剂回收再加工，依托 20 余年贵金属催化、提纯、回收全链条积累切入半导体 ALD 高纯贵金属有机前驱体赛道。","round":"已上市","lastFunding":"-","tech":[{"date":"2026-01","title":"电化学合成专利进入实质审查","kind":"技术","desc":"专利号 CN202511386838.3，摒弃传统王水高温氯化路线，采用贵金属同材质电极电解溶解 + 两级螯合树脂深度除杂，一套工艺兼容铂、钯、铑、铱、钌、金六大芯片贵金属。"},{"date":"2026-06","title":"AN5 类 5N 级高纯贵金属前驱体小试送样","kind":"技术","desc":"实测产物纯度稳定 5N~6N：氯化钯 99.9997%、三氯化金 99.9996%、氯铂酸 99.9994%。用于先进制程栅极、阻挡层、互连线路与 HBM 存储电极。"}],"note":"【卡脖子定位】全球半导体贵金属 ALD 前驱体仅默克、巴斯夫、住友化学三家稳定量产。国内该品类 2026 年采购规模约 50 亿元，国产市占率不足 30%，且国内同行大多只能做 3N~4N 普通贵金属化合物，纯度不满足先进晶圆产线准入。凯立是国内极少数打通研发 + 小试送样的厂商。"}'::jsonb),
  ('贵研铂业', 'semiconductor', 'material', true, '已上市', null, null, null, '{"name":"贵研铂业","industry":"semiconductor","seg":"material","listed":true,"desc":"云南省贵金属新材料控股集团，国内贵金属新材料领域集产学研用于一体的平台型上市公司，业务涵盖贵金属资源循环利用、新材料制造与供给服务三大板块。半导体材料方面布局蒸发材料、键合丝、铜丝及镀钯铜丝、贵金属前驱体。","round":"已上市","lastFunding":"-","tech":[{"date":"2026-08","title":"超细键合金丝达国际领先水平","kind":"技术","desc":"上半年突破关键技术 4 项。铜丝、镀钯铜丝产品实现批量送样落地。"},{"date":"2026-08","title":"半导体核心客户销量同比增长 6%","kind":"客户","desc":"受益 AI 算力建设与存储涨价周期拉动上游电子贵金属基础材料需求，行业呈现「低端内卷、高端紧缺」的结构性行情。"},{"date":"2026-06","title":"6N 级钌/铂系 ALD 前驱体国内唯一量产","kind":"技术","desc":"贵金属前驱体材料收入 35.31 亿元，占营收 15.59%。长江存储 / 长鑫存储 / 中芯国际已导入。"}],"executives":[{"name":"—","title":"（云南省国资委控股平台）","role":"board"}],"note":"【卡脖子定位】贵金属前驱体是 HBM、3D NAND、先进逻辑的命脉材料，纯度不够则良率归零。贵研是国内唯一具备钌/铂/铱/钯/金贵金属前驱体全链条量产能力的企业，同时具备贵金属回收闭环（上半年回收产出铂族金属 10 吨、黄金 5.59 吨），原材料成本优势显著。"}'::jsonb),
  ('中巨芯', 'semiconductor', 'material', true, '已上市', null, null, null, '{"name":"中巨芯","industry":"semiconductor","seg":"material","listed":true,"desc":"中巨芯科技股份有限公司，深耕半导体制造支撑业，业务分电子湿化学品与电子特种气体及前驱体两大板块。2026 年上半年电子特种气体及前驱体板块营收 2.85 亿元，同比增长 136.78%。","round":"已上市","lastFunding":"-","tech":[{"date":"2026-09","title":"举办投资者开放日，明确二五战略","kind":"公司","desc":"管理层表示产能扩张将结合客户验证进度与市场拓展节奏稳步推进，不盲目跟风。"},{"date":"2026-08","title":"电子特气及前驱体板块营收同比增 136.78%","kind":"业绩","desc":"上半年总营收 7.99 亿元（+40.98%），归母净利润 1,405.77 万元（+72.75%）。电子湿化学品板块营收 4.92 亿元。"}],"executives":[{"name":"陈刚","title":"董事、总经理","role":"management"},{"name":"贺辉龙","title":"副总经理","role":"management"},{"name":"陈东强","title":"副总经理","role":"management"},{"name":"陈立峰","title":"董事会秘书","role":"management"}],"note":"【卡脖子定位】前驱体整体国产化率约 15%，远低于湿电子化学品（45%）、靶材（35%）、电子特气（30%）。分品类看高 K 前驱体（铪/锆）<5%、钴/钌前驱体（3nm+）≈0%，完全依赖日美欧巨头。中巨芯是国产前驱体第一阵营成员（内资 CR4 之一）。"}'::jsonb),
  ('先导微电子', 'semiconductor', 'material', false, '—', null, null, null, '{"name":"先导微电子","industry":"semiconductor","seg":"material","listed":false,"desc":"先导微电子（先导智能子公司体系），主攻四氯化铪（高 K 前驱体）与二氯二氧化钼（钼前驱体），6N 级高纯铪前驱体稳定量产，为长江存储、长鑫存储核心供应商。四氯化铪国内市占率 80% 以上。","round":"—","lastFunding":"-","tech":[{"date":"2026-06","title":"四氯化铪国内市占率超 80%","kind":"市场","desc":"6N 级高纯铪前驱体稳定量产，为国内高 K 前驱体最主要供应商。"},{"date":"2026-06","title":"钼前驱体进入 HBM 产线导入","kind":"客户","desc":"钨/钼前驱体国产化率整体仍 <10%，先导微电子为第一梯队。"}],"investorsStructured":[{"name":"先导智能","role":"strategic","kind":"cvc","note":"母公司体系，锂电设备龙头跨界半导体材料"}],"note":"【卡脖子定位】高 K 前驱体（铪/锆）国产化率 <5%，是先进制程与 HBM 的关键卡点。先导微电子在四氯化铪这一细分上做到了国内 80%+ 市占，是国内最接近「单点突破」的前驱体企业。"}'::jsonb),
  ('昊华科技', 'semiconductor', 'material', true, '已上市', null, null, null, '{"name":"昊华科技","industry":"semiconductor","seg":"material","listed":true,"desc":"昊华化工科技集团股份有限公司，央企中国中化旗下化工新材料平台，在半导体材料领域布局钨/钼前驱体研发，目前处于送样验证阶段；同时是国内高端含氟电子气体主力供应商之一。","round":"已上市","lastFunding":"-","tech":[{"date":"2026-06","title":"钨/钼前驱体送样验证中","kind":"技术","desc":"钨/钼前驱体（WF₆/MoF₆）国产化率整体 <10%，HBM 产线导入是主要增量场景。"}],"note":"【卡脖子定位】央企平台型材料公司，前驱体是其半导体业务的延展方向，主战场仍在含氟电子气体。钨/钼前驱体是 HBM 扩产的关键耗材。"}'::jsonb),
  ('格林达', 'semiconductor', 'material', true, '已上市', null, null, null, '{"name":"格林达","industry":"semiconductor","seg":"material","listed":true,"desc":"杭州格林达电子材料股份有限公司，半导体专用 TMAH 显影液国内市占第一，产品为 EUV 光刻配套刚需耗材。2025 年 12 月通过国家级制造业单项冠军示范企业复核（认证产品「TMAH 显影液」）。","round":"已上市","lastFunding":"-","tech":[{"date":"2026-05","title":"工信部显影液项目通过整体验收","kind":"技术","desc":"与国内芯片龙头企业联合开展大规模集成电路用图形化显影液产品的研发及产业化应用验证，完成龙头客户端供应商资格审查导入。"},{"date":"2026-06","title":"G5 级显影液在中芯国际、华虹批量供货","kind":"客户","desc":"在长鑫存储小批量爬坡，在长江存储处于产线验证收尾阶段。另在华星光电广州工厂实现量供，通过韩国 LGD 直供供应商全面稽核。"}],"executives":[{"name":"方伟华","title":"总经理","role":"management"},{"name":"何婷茹","title":"财务总监","role":"management"},{"name":"章琪","title":"董事会秘书","role":"management"}],"note":"【卡脖子定位】显影液是光刻胶配套化学品中用量最大、纯度要求最高的品类，直接对应光刻精度。格林达是国内 TMAH 显影液单项冠军，G5 级产品已在头部晶圆厂批量供货，是光刻胶配套环节国产化程度最高的单品之一。"}'::jsonb),
  ('八亿时空', 'semiconductor', 'material', true, '已上市', null, null, null, '{"name":"八亿时空","industry":"semiconductor","seg":"material","listed":true,"desc":"北京八亿时空液晶科技股份有限公司，以液晶材料为主业，在半导体领域攻克 KrF 制程 PHS 酚醛树脂（光刻胶核心骨架原料），是国内唯一对外规模化外销 KrF 光刻树脂的厂商。","round":"已上市","lastFunding":"-","tech":[{"date":"2026-06","title":"KrF 光刻胶树脂实现规模化生产","kind":"技术","desc":"已在晶圆厂验证通过并实现量产，更大规模量产线建设推进中。供货客户包括彤程新材、徐州博康、晶瑞电材。"}],"note":"【卡脖子定位】光刻胶的卡脖子已深入到最上游的树脂、光酸单体等基础原材料，部分 100% 依赖进口。八亿时空是国产 KrF 光刻树脂的唯一规模化外销方，日系树脂供给收缩直接受益。"}'::jsonb),
  ('宏昌电子', 'semiconductor', 'material', true, '已上市', null, null, null, '{"name":"宏昌电子","industry":"semiconductor","seg":"material","listed":true,"desc":"宏昌电子材料股份有限公司，电子级环氧树脂厂商，2023 年起与台湾晶化科技合作开发 GBF 先进封装增层膜（类 ABF 膜）。同时具备树脂合成、膜材制造与覆铜板三位一体能力，成本控制具备潜在优势。","round":"已上市","lastFunding":"-","tech":[{"date":"2026-09","title":"抛出 18 亿元定增，建 384 万平方米 GBF 产能","kind":"产能","desc":"规划年产 384 万平方米 GBF 先进封装膜材，规划产能压过华正新材现有规模。产品已完成国内头部封测厂验证。"},{"date":"2026-08","title":"GBF 膜进入华为昇腾备选供应链","kind":"客户","desc":"GBF C+ G10 产品已通过下游板厂认证，完成国内头部封测厂验证和小批量试产，规划 2026 年四季度规模放量。"}],"note":"【卡脖子定位】ABF 膜（积层绝缘膜）是高端 FC-BGA 载板的核心绝缘材料，日本味之素全球份额超 95%，2026 年 8 月通知中国大陆客户削减 30% 供货并同步涨价（最高 30%）。中国大陆 ABF 膜自给率不足 5%。宏昌电子走环氧体系路线，是国内「砸钱最狠的后发者」。"}'::jsonb),
  ('激智科技', 'semiconductor', 'material', true, '已上市', null, null, null, '{"name":"激智科技","industry":"semiconductor","seg":"material","listed":true,"desc":"宁波激智科技股份有限公司，核心能力为精密涂布，已大量生产光学扩散膜、增亮膜、量子点膜等功能性薄膜。ABF 膜同样需要精密涂布、烘干与成膜，公司据此向电子功能膜（类 ABF 介电膜）延伸。","round":"已上市","lastFunding":"-","tech":[{"date":"2026-08","title":"新型介电膜启动头部载板厂送样测试","kind":"技术","desc":"依托光学涂布技术开发，样品性能接近日本进口产品，计划 2026 年 8 月启动测试。"}],"note":"【卡脖子定位】ABF 类膜国产替代第二梯队。激智科技的优势是现有涂布产能与工艺积累，属「技术基础具备、验证刚起步」阶段。"}'::jsonb),
  ('天承科技', 'semiconductor', 'material', true, '已上市', null, null, null, '{"name":"天承科技","industry":"semiconductor","seg":"material","listed":true,"desc":"广东天承科技股份有限公司，PCB 与 IC 载板专用电子化学品厂商，主营水平沉铜、电镀等湿制程药水。ABF 载板配套 SAP（半加成法）制程药水目前处于中试阶段。","round":"已上市","lastFunding":"-","tech":[{"date":"2026-08","title":"ABF 载板配套 SAP 制程药水中试","kind":"技术","desc":"SAP 制程药水是 ABF 载板精细线路成型的核心耗材，长期由日系厂商主导。"}],"note":"【卡脖子定位】ABF 载板国产化的配套环节——除膜材外，SAP 制程药水同样依赖进口。天承科技是国内少数切入该环节的厂商。"}'::jsonb),
